mapper.select:
select u.id, u.username, u.nickname, u.role, u.phone, u.merchant_id, u.health_goal, u.preference, u.taboo, u.status, u.create_time, u.update_time, m.name merchantName from user u left join merchant m on u.merchant_id = m.id
u.username like CONCAT('%', #{username}, '%')
and u.role = #{role}
and u.status = #{status}
order by u.update_time desc
